+
+        private void CheckPermission()
+        {
+            btnAdd.Enabled = mnuItemAdd.Enabled = UserSession.HasPermission(PERMISSION_ADD);
+            btnEdit.Text = mnuItemEdit.Text = UserSession.HasPermission(PERMISSION_EDIT) ? "Sửa" : "Xem";
+            UpdateListButtonState();
+        }
+
+        private void UpdateListButtonState()
+        {
+            bool haveRow = gvData.GetFocusedDataRow() != null;
+            btnEdit.Enabled = mnuItemEdit.Enabled = haveRow && UserSession.HasPermission(PERMISSION_VIEW);
+            btnDelete.Enabled = mnuItemDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_DELETE);
+        }
+
+        public void LoadReferenceData()
+        {
+            if (InvokeRequired)
+                Invoke(new MethodInvoker(LoadReferenceData));
+            else
+            {
+                try
+                {
+                    if (bolIsRefresh)
+                    {
+                        HRS_EmployeeService.HaveNewData = true;
+                        SMS_ItemGroupService.HaveNewData = true;
+                        SMS_ItemService.HaveNewData = true;
+                    }
+                    HRS_EmployeeService.InitLookUpEdit(lookupEmployeeSearch);
+                    HRS_EmployeeService.InitLookUpEdit(lookupEmployee);
+                    DataTable groupTable = SMS_ItemGroupService.Table;
+                    DataRow[] groupRows = groupTable.Select(
+                        SMS_ItemGroup.C_ItemGroupCode + " = 'CCDC-BHLD'");
+                    if (groupRows.Length == 0 || groupRows[0][SMS_ItemGroup.C_ItemGroupID] == DBNull.Value)
+                    {
+                        lookupItemSearch.DataSource = null;
+                        lookupItem.DataSource = null;
+                        MessageManager.Warning("Không tìm thấy nhóm hàng có mã CCDC-BHLD.");
+                        bolIsRefresh = false;
+                        return;
+                    }
+                    int itemGroupID = Convert.ToInt32(groupRows[0][SMS_ItemGroup.C_ItemGroupID]);
+                    string condition = "ItemGroupID = " + Convert.ToString(itemGroupID);
+                    SMS_ItemService.InitLookUpEdit(lookupItemSearch, condition);
+                    SMS_ItemService.InitLookUpEdit(lookupItem, condition);
+                    bolIsRefresh = false;
+                }
+                catch (Exception objEx)
+                {
+                    ErrorManager.Error(objEx);
+                    SYS_ErrorLogService.Write(Enums.ActionType.View, "frmLaborProtectionIssue->LoadReferenceData", objEx, 0);
+                }
+            }
+        }
+
+        public void LoadData()
+        {
+            if (InvokeRequired)
+                Invoke(new MethodInvoker(LoadData));
+            else
+            {
+                try
+                {
+                    FAM_LaborProtectionIssue obj = new FAM_LaborProtectionIssue();
+                    DataTable table = obj.Search(
+                        dtmFromDate.EditValueDate,
+                        dtmToDate.EditValueDate,
+                        lookupEmployeeSearch.EditValueInt32,
+                        lookupItemSearch.EditValueInt64,
+                        txtKeyword.TextTrim);
+                    if (table == null)
+                    {
+                        ErrorManager.Error("Không tải được danh sách cấp bảo hộ lao động. " +
+                            (obj.ErrorException == null ? "" : obj.ErrorException.Message));
+                        return;
+                    }
+                    gcData.DataSource = table;
+                    SYS_GridColumnService.InitGridColumn(gvData, "FAM_LaborProtectionIssue_Search", bolIsRefresh);
+                    gvData.OptionsBehavior.Editable = false;
+                    if (itemEditing.LaborProtectionIssueID.HasValue)
+                        gvData.SearchAndSelectRow(FAM_LaborProtectionIssue.C_LaborProtectionIssueID, itemEditing.LaborProtectionIssueID.Value);
+                    UpdateListButtonState();
+                }
+                catch (Exception objEx)
+                {
+                    ErrorManager.Error(objEx);
+                    SYS_ErrorLogService.Write(Enums.ActionType.View, "frmLaborProtectionIssue->LoadData", objEx, 0);
+                }
+            }
+        }
+
+        private FAM_LaborProtectionIssue GetFocusedItem()
+        {
+            DataRow row = gvData.GetFocusedDataRow();
+            if (row == null)
+                return null;
+            FAM_LaborProtectionIssue item = new FAM_LaborProtectionIssue();
+            if (!item.Parse(row) || !item.LaborProtectionIssueID.HasValue)
+                return null;
+            DataTable table = item.GetByID(item.LaborProtectionIssueID.Value);
+            if (table == null || table.Rows.Count == 0)
+                return item;
+            FAM_LaborProtectionIssue loadedItem = new FAM_LaborProtectionIssue();
+            return loadedItem.Parse(table.Rows[0]) ? loadedItem : item;
+        }
+
+        private void ShowEditForm(FAM_LaborProtectionIssue item)
+        {
+            if (item == null)
+            {
+                itemEditing = new FAM_LaborProtectionIssue();
+                dtmIssueDate.EditValue = DateTime.Today;
+                lookupItem.EditValue = null;
+                lookupEmployee.EditValue = null;
+                calcQuantity.EditValue = 1M;
+                calcAllowanceAmount.EditValue = null;
+                txtIssueNote.TextTrim = "";
+                txtDescription.TextTrim = "";
+                btnSaveEdit.Enabled = UserSession.HasPermission(PERMISSION_ADD);
+            }
+            else
+            {
+                itemEditing = item;
+                dtmIssueDate.EditValue = item.IssueDate;
+                lookupItem.EditValue = item.ItemID;
+                lookupEmployee.EditValue = item.EmployeeID;
+                calcQuantity.EditValue = item.Quantity;
+                calcAllowanceAmount.EditValue = item.AllowanceAmount;
+                txtIssueNote.TextTrim = item.IssueNote == null ? "" : item.IssueNote;
+                txtDescription.TextTrim = item.Description == null ? "" : item.Description;
+                btnSaveEdit.Enabled = UserSession.HasPermission(PERMISSION_EDIT);
+            }
+            SetDetailReadOnly(!btnSaveEdit.Enabled);
+            bolIsEditing = true;
+            tcData.SelectedTabPage = tpDetail;
+            dtmIssueDate.Focus();
+        }
+
+        private void SetDetailReadOnly(bool readOnly)
+        {
+            dtmIssueDate.ReadOnly = readOnly;
+            lookupItem.ReadOnly = readOnly;
+            lookupEmployee.ReadOnly = readOnly;
+            calcQuantity.ReadOnly = readOnly;
+            calcAllowanceAmount.ReadOnly = readOnly;
+            txtIssueNote.ReadOnly = readOnly;
+            txtDescription.ReadOnly = readOnly;
+        }
+
+        private bool IsValidEditForm()
+        {
+            if (!dtmIssueDate.EditValueDate.HasValue)
+            {
+                MessageManager.Warning("Bạn phải chọn ngày cấp!");
+                dtmIssueDate.Focus();
+                return false;
+            }
+            if (!lookupItem.EditValueInt64.HasValue)
+            {
+                MessageManager.Warning("Bạn phải chọn CCDC/BHLD!");
+                lookupItem.Focus();
+                return false;
+            }
+            if (!lookupEmployee.EditValueInt32.HasValue)
+            {
+                MessageManager.Warning("Bạn phải chọn nhân viên!");
+                lookupEmployee.Focus();
+                return false;
+            }
+            if (!calcQuantity.EditValueDecimal.HasValue || calcQuantity.EditValueDecimal.Value <= 0)
+            {
+                MessageManager.Warning("Số lượng phải lớn hơn 0!");
+                calcQuantity.Focus();
+                return false;
+            }
+            if (calcAllowanceAmount.EditValueDecimal.HasValue && calcAllowanceAmount.EditValueDecimal.Value < 0)
+            {
+                MessageManager.Warning("Tiền phụ cấp phải lớn hơn hoặc bằng 0!");
+                calcAllowanceAmount.Focus();
+                return false;
+            }
+            return true;
+        }
+
+        private bool SaveEditForm()
+        {
+            try
+            {
+                bool isAdd = !itemEditing.LaborProtectionIssueID.HasValue;
+                FAM_LaborProtectionIssue item = new FAM_LaborProtectionIssue();
+                item.LaborProtectionIssueID = itemEditing.LaborProtectionIssueID;
+                item.IssueDate = dtmIssueDate.EditValueDate;
+                item.ItemID = lookupItem.EditValueInt64;
+                item.EmployeeID = lookupEmployee.EditValueInt32;
+                item.Quantity = calcQuantity.EditValueDecimal;
+                item.AllowanceAmount = calcAllowanceAmount.EditValueDecimal;
+                item.IssueNote = txtIssueNote.TextTrim;
+                item.Description = txtDescription.TextTrim;
+                bool result;
+                if (isAdd)
+                {
+                    item.CreatedUser = UserSession.Username;
+                    result = item.Add();
+                }
+                else
+                {
+                    item.UpdatedUser = UserSession.Username;
+                    result = item.Update();
+                }
+                if (!result)
+                {
+                    ErrorManager.Error("Không lưu được thông tin cấp bảo hộ lao động. " +
+                        (item.ErrorException == null ? "" : item.ErrorException.Message));
+                    return false;
+                }
+                itemEditing = item;
+                SYS_ActionLogService.Write(
+                    isAdd ? Enums.ActionType.Add : Enums.ActionType.Edit,
+                    isAdd ? "Thêm cấp bảo hộ lao động" : "Cập nhật cấp bảo hộ lao động",
+                    Convert.ToString(item.LaborProtectionIssueID),
+                    0);
+                return true;
+            }
+            catch (Exception objEx)
+            {
+                ErrorManager.Error(objEx);
+                SYS_ErrorLogService.Write(Enums.ActionType.Edit, "frmLaborProtectionIssue->SaveEditForm", objEx, 0);
+                return false;
+            }
+        }
+
+        private bool DeleteData()
+        {
+            int[] selectedRows = gvData.GetSelectedRows();
+            for (int i = selectedRows.Length - 1; i >= 0; i--)
+            {
+                DataRow row = gvData.GetDataRow(selectedRows[i]);
+                if (row == null || row[FAM_LaborProtectionIssue.C_LaborProtectionIssueID] == DBNull.Value)
+                    continue;
+                long id = Convert.ToInt64(row[FAM_LaborProtectionIssue.C_LaborProtectionIssueID]);
+                FAM_LaborProtectionIssue obj = new FAM_LaborProtectionIssue();
+                if (!obj.Delete(id))
+                {
+                    ErrorManager.Error("Không xóa được thông tin cấp bảo hộ lao động. " +
+                        (obj.ErrorException == null ? "" : obj.ErrorException.Message));
+                    return false;
+                }
+                gvData.DeleteRow(selectedRows[i]);
+                SYS_ActionLogService.Write(Enums.ActionType.Delete, "Xóa cấp bảo hộ lao động", Convert.ToString(id), 0);
+            }
+            return true;
+        }
+
