+        private void frmLaborProtectionIssue_Load(object sender, EventArgs e)
+        {
+            DateTime today = DateTime.Today;
+            dtmFromDate.EditValue = new DateTime(today.Year, today.Month, 1);
+            dtmToDate.EditValue = today;
+            CheckPermission();
+            SetToolTip();
+            new Thread(LoadReferenceData).Start();
+            new Thread(LoadData).Start();
+        }
+
