+        {
+            new Thread(LoadData).Start();
+        }
+
+        private void btnAdd_Click(object sender, EventArgs e)
+        {
+            ShowEditForm(null);
+        }
+
+        private void btnEdit_Click(object sender, EventArgs e)
+        {
+            FAM_LaborProtectionIssue item = GetFocusedItem();
+            if (item != null)
+                ShowEditForm(item);
+        }
+
+        private void btnDelete_Click(object sender, EventArgs e)
+        {
+            if (MessageManager.Confirm("Bạn thực sự muốn xóa những dữ liệu đã chọn?") == DialogResult.Yes)
+                DeleteData();
+            UpdateListButtonState();
+        }
+
+        private void btnSaveEdit_Click(object sender, EventArgs e)
+        {
+            if (IsValidEditForm() && SaveEditForm())
+            {
+                bolIsEditing = false;
+                tcData.SelectedTabPage = tpList;
+                new Thread(LoadData).Start();
+            }
+        }
+
+        private void btnBack_Click(object sender, EventArgs e)
+        {
+            bolIsEditing = false;
+            tcData.SelectedTabPage = tpList;
+        }
+
+        private void btnClose_Click(object sender, EventArgs e)
+        {
+            Close();
+        }
+
+        private void mnuItemRefresh_Click(object sender, EventArgs e)
+        {
+            bolIsRefresh = true;
+            new Thread(LoadReferenceData).Start();
+            new Thread(LoadData).Start();
+        }
+
+        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
+        {
+            gvData.QuickExportToExcel();
+        }
+
+        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
+        {
+            UpdateListButtonState();
+        }
+
+        private void tcData_SelectedPageChanging(object sender, DevExpress.XtraTab.TabPageChangingEventArgs e)
+        {
+            if ((!bolIsEditing && e.Page == tpDetail) || (bolIsEditing && e.Page == tpList))
+                e.Cancel = true;
+        }
+
+        private void frmLaborProtectionIssue_KeyDown(object sender, KeyEventArgs e)
+        {
+            switch (e.KeyData)
+            {
+                case Keys.F2:
+                    if (!bolIsEditing && btnEdit.Enabled)
+                        btnEdit_Click(sender, null);
+                    break;
+                case Keys.F4:
+                    if (!bolIsEditing && btnDelete.Enabled)
+                        btnDelete_Click(sender, null);
+                    break;
+                case Keys.F5:
+                    mnuItemRefresh_Click(sender, null);
+                    break;
+                case Keys.F6:
+                    if (bolIsEditing && btnSaveEdit.Enabled)
+                        btnSaveEdit_Click(sender, null);
+                    break;
+                case Keys.F8:
+                    if (!bolIsEditing && btnAdd.Enabled)
+                        btnAdd_Click(sender, null);
+                    break;
+                case Keys.Escape:
+                    if (bolIsEditing)
+                        btnBack_Click(sender, null);
+                    else
+                        Close();
+                    break;
+            }
+        }
+
+        #endregion
+    }
+}
